# Enrich each catalog item with reliable external-reading metadata.
for t in texts:
    title=t.get('titleEn') or t.get('titleHi') or t['slug']
    q=urllib.parse.quote(f'"{title}"')
    t['archiveUrl']=f'https://archive.org/search?query={q}'
    t['archiveLabelEn']='Find public editions on Internet Archive'
    t['archiveLabelHi']='Internet Archive पर सार्वजनिक संस्करण देखें'
    if t['slug'] in direct:
        label,url=direct[t['slug']]
        t['readOnlineUrl']=url
        t['readOnlineLabelEn']=label
        t['readOnlineLabelHi']='ऑनलाइन ग्रंथ पढ़ें'
    else:
        t['readOnlineUrl']=''
        t['readOnlineLabelEn']=''
        t['readOnlineLabelHi']=''

    # Replace repetitive boilerplate with title-specific, description-led text.
    desc_en=t.get('descriptionEn','').strip()
    desc_hi=t.get('descriptionHi','').strip()
    kind_en=t.get('kindEn','text')
    kind_hi=t.get('kindHi','ग्रंथ')
    cat_en=t.get('category','Hindu textual tradition')
    cat_hi=t.get('categoryHi','हिंदू ग्रंथ-परंपरा')
    t['keyThemesEn']=f"{title} is best approached through the themes already visible in its own composition: {desc_en.rstrip('.')} This page keeps those themes connected to the work's genre, transmission and place in {cat_en}."
    t['keyThemesHi']=f"{t.get('titleHi',title)} को उसके अपने विषय-विन्यास से समझना सबसे उपयोगी है: {desc_hi.rstrip('।')}। इस पृष्ठ में इन विषयों को ग्रंथ की विधा, पाठ-परंपरा और {cat_hi} में उसके स्थान से जोड़ा गया है।"
    t['structureEn']=f"As a {kind_en}, {title} should be read according to the internal divisions of the edition or recension in hand. Chapter, book, kanda, mandala, sutra or hymn numbering can vary across textual traditions, so the edition name matters when citing passages."
    t['structureHi']=f"{kind_hi} के रूप में {t.get('titleHi',title)} की आंतरिक रचना प्रयुक्त संस्करण या शाखा के अनुसार पढ़ी जानी चाहिए। अध्याय, कांड, मंडल, सूत्र या सूक्त की संख्या अलग पाठ-परंपराओं में कुछ भिन्न हो सकती है, इसलिए उद्धरण देते समय संस्करण का नाम महत्वपूर्ण है।"
    t['studyNoteEn']=f"Begin {title} with a clearly identified edition or translation. Keep the base text, translator's wording and later commentary distinct; this makes comparison between traditions more respectful and accurate."
    t['studyNoteHi']=f"{t.get('titleHi',title)} का अध्ययन किसी स्पष्ट रूप से पहचाने गए संस्करण या अनुवाद से शुरू करें। मूल पाठ, अनुवादक की भाषा और बाद की टीका को अलग पहचानना विभिन्न परंपराओं की तुलना को अधिक सम्मानपूर्ण और सटीक बनाता है।"

# Curated, respectful 'Understand Sanatan' topics. These are explanations, not attack/rebuttal cards.
topics=[
('33-koti-devata','33 Koti Devata: how should the expression be understood?','33 कोटि देवता: इस अभिव्यक्ति को कैसे समझें?','Hindu traditions speak of divine plurality in more than one way. Vedic texts also enumerate groups of thirty-three deities, while later devotional language uses much larger numbers to express the vastness of divine forms.','हिंदू परंपराएँ दिव्यता की बहुलता को अनेक ढंग से व्यक्त करती हैं। वैदिक ग्रंथों में तैंतीस देवताओं के समूहों का उल्लेख मिलता है, जबकि बाद की भक्तिपरंपराओं में बहुत बड़ी संख्याएँ दिव्य रूपों की विशालता को व्यक्त करती हैं।'),
('one-truth-many-forms','One truth, many divine forms','एक सत्य, अनेक दिव्य रूप','Many Hindu schools distinguish the supreme reality from the many names and forms through which devotees approach it. This makes plurality and unity compatible rather than mutually exclusive.','अनेक हिंदू दर्शन परम सत्य और उन अनेक नाम-रूपों में भेद करते हैं जिनके माध्यम से भक्त उसकी उपासना करते हैं। इसलिए एकता और विविधता परस्पर विरोधी नहीं मानी जातीं।'),
('murti-puja-meaning','What is the meaning of Murti Puja?','मूर्ति-पूजा का अर्थ क्या है?','A murti functions as a consecrated focus of worship, remembrance and relationship with the divine. Hindu theology does not require the infinite reality to be limited to the physical material of an image.','मूर्ति उपासना, स्मरण और दिव्य संबंध का प्रतिष्ठित केंद्र होती है। हिंदू दर्शन परम सत्य को केवल मूर्ति की भौतिक सामग्री तक सीमित नहीं मानता।'),
('ishta-devata','What is Ishta Devata?','इष्ट देवता क्या है?','Ishta Devata is the personally cherished form of the divine through which a devotee may cultivate prayer, love and contemplation while respecting other forms of worship.','इष्ट देवता वह प्रिय दिव्य स्वरूप है जिसके माध्यम से भक्त प्रार्थना, प्रेम और ध्यान का संबंध विकसित करता है, साथ ही अन्य उपासना-रूपों का सम्मान रख सकता है।'),
('saguna-nirguna','Saguna and Nirguna Brahman','सगुण और निर्गुण ब्रह्म','Hindu philosophy allows reflection on the divine both with attributes and beyond limiting attributes. Different Vedanta traditions explain the relationship in different ways.','हिंदू दर्शन में दिव्यता को गुणों सहित भी और सीमित गुणों से परे भी चिंतन किया जाता है। विभिन्न वेदांत परंपराएँ इनके संबंध को अलग-अलग ढंग से समझाती हैं।'),
('brahman-brahma-brahmin','Brahman, Brahma and Brahmin are not the same term','ब्रह्मन्, ब्रह्मा और ब्राह्मण एक ही शब्द नहीं हैं','Brahman commonly refers to ultimate reality in philosophical texts; Brahma is a deity; Brahmin is a social and ritual term. Similar spelling in English can hide very different Sanskrit words.','ब्रह्मन् दार्शनिक ग्रंथों में परम वास्तविकता का सूचक है; ब्रह्मा एक देवता हैं; ब्राह्मण सामाजिक और अनुष्ठानिक शब्द है। अंग्रेज़ी वर्तनी की समानता इन संस्कृत शब्दों के भेद को छिपा सकती है।'),
('divinity-everywhere','The sacredness of life and nature','जीवन और प्रकृति में पवित्रता','Many Hindu texts and living traditions encourage seeing the world as pervaded by sacred presence. This supports reverence toward people, animals, rivers, mountains, plants and the elements without making every tradition identical.','अनेक हिंदू ग्रंथ और जीवित परंपराएँ जगत को पवित्र उपस्थिति से व्याप्त देखने की प्रेरणा देती हैं। इससे मनुष्य, पशु, नदी, पर्वत, वृक्ष और तत्वों के प्रति आदर का भाव विकसित होता है, यद्यपि सभी परंपराएँ बिल्कुल एक जैसी नहीं हैं।'),
('vasudhaiva-kutumbakam','Vasudhaiva Kutumbakam','वसुधैव कुटुम्बकम्','The well-known expression presents a moral imagination in which narrow self-interest is surpassed by a wider sense of kinship. It is best read in its textual context rather than reduced to a slogan.','यह प्रसिद्ध अभिव्यक्ति संकीर्ण स्वार्थ से ऊपर उठकर व्यापक आत्मीयता का नैतिक दृष्टिकोण प्रस्तुत करती है। इसे केवल नारे की तरह नहीं, उसके ग्रंथीय संदर्भ में समझना अधिक उचित है।'),
('sarve-bhavantu-sukhinah','Sarve Bhavantu Sukhinah','सर्वे भवन्तु सुखिनः','This prayer expresses a wish for the well-being, health and freedom from suffering of all. Its continuing popularity reflects a broad ethical aspiration of welfare beyond the self.','यह प्रार्थना सभी के सुख, स्वास्थ्य और दुःख से मुक्ति की कामना व्यक्त करती है। इसकी निरंतर लोकप्रियता स्वयं से परे व्यापक कल्याण की नैतिक आकांक्षा को दर्शाती है।'),
('atithi-devo-bhava','Atithi Devo Bhava','अतिथि देवो भव','The Taittiriya Upanishad places hospitality alongside reverence for mother, father and teacher. The phrase teaches the householder to receive a guest with dignity and care.','तैत्तिरीय उपनिषद अतिथि-सम्मान को माता, पिता और आचार्य के सम्मान के साथ रखता है। यह वाक्य गृहस्थ को अतिथि का आदर और देखभाल के साथ स्वागत करने की शिक्षा देता है।'),
('matru-pitru-acharya','Matru Devo Bhava, Pitru Devo Bhava, Acharya Devo Bhava','मातृ देवो भव, पितृ देवो भव, आचार्य देवो भव','These teachings express gratitude and reverence toward those who nurture, protect and educate. Reverence is an ethical discipline of gratitude, not a claim that human beings are beyond all moral judgment.','ये शिक्षाएँ पालन-पोषण, संरक्षण और शिक्षा देने वालों के प्रति कृतज्ञता और सम्मान व्यक्त करती हैं। यह सम्मान कृतज्ञता का नैतिक अनुशासन है, न कि मनुष्य को सभी नैतिक प्रश्नों से परे मानना।'),
('dharma-not-only-religion','Dharma is broader than the English word religion','धर्म का अर्थ केवल religion नहीं है','Depending on context, dharma can refer to duty, ethical order, sustaining principle, right conduct, law, teaching or religious path. No single English word captures every use.','संदर्भ के अनुसार धर्म का अर्थ कर्तव्य, नैतिक व्यवस्था, धारण करने वाला सिद्धांत, सदाचार, विधि, शिक्षा या आध्यात्मिक मार्ग हो सकता है। कोई एक अंग्रेज़ी शब्द इसके सभी प्रयोगों को नहीं समेटता।'),
('karma-not-fate','Karma is not simply fate','कर्म केवल भाग्य नहीं है','Karma is fundamentally connected with action and its consequences. Hindu schools differ on details, but the concept leaves an important place for present choices, discipline and ethical responsibility.','कर्म मूलतः क्रिया और उसके परिणाम से जुड़ा है। विवरण में दर्शन-परंपराएँ भिन्न हो सकती हैं, पर वर्तमान चुनाव, अनुशासन और नैतिक जिम्मेदारी के लिए महत्वपूर्ण स्थान बना रहता है।'),
('moksha-not-heaven','Moksha is not merely heaven','मोक्ष केवल स्वर्ग नहीं है','Moksha generally refers to liberation from bondage and the cycle of rebirth, though schools explain its nature differently. Heaven in many texts can still be a conditioned or temporary realm.','मोक्ष सामान्यतः बंधन और पुनर्जन्म के चक्र से मुक्ति का संकेत है, यद्यपि विभिन्न दर्शन इसकी प्रकृति अलग ढंग से बताते हैं। अनेक ग्रंथों में स्वर्ग भी सशर्त या अस्थायी लोक हो सकता है।'),
('yoga-more-than-exercise','Yoga is more than physical exercise','योग केवल शारीरिक व्यायाम नहीं है','Classical and devotional yoga traditions include ethics, discipline, breath, concentration, meditation, knowledge and devotion in addition to bodily practice.','शास्त्रीय और भक्तिपरक योग परंपराओं में शारीरिक अभ्यास के साथ नैतिकता, अनुशासन, प्राण, एकाग्रता, ध्यान, ज्ञान और भक्ति भी शामिल हैं।'),
('nature-sacred','Why is nature treated as sacred?','प्रकृति को पवित्र क्यों माना जाता है?','Rivers, mountains, trees, animals, the Sun, Earth and the elements appear in ritual, poetry and theology because the natural world is experienced as life-giving and spiritually meaningful.','नदियाँ, पर्वत, वृक्ष, पशु, सूर्य, पृथ्वी और तत्व अनुष्ठान, काव्य और दर्शन में इसलिए आते हैं क्योंकि प्रकृति जीवनदायिनी और आध्यात्मिक अर्थ से युक्त मानी जाती है।'),
('prithvi-mata','Why is Earth called Mother?','पृथ्वी को माता क्यों कहा जाता है?','The image of Prithvi as mother expresses dependence, nourishment, gratitude and responsibility toward the land that sustains life.','पृथ्वी को माता कहना जीवन-धारण, पोषण, कृतज्ञता और उस भूमि के प्रति जिम्मेदारी की भावना व्यक्त करता है जो जीवों को धारण करती है।'),
('surya-upasana','What does Surya worship express?','सूर्य उपासना क्या व्यक्त करती है?','Surya is honored as a visible source of light, time and life. Ritual reverence and astronomical observation developed in distinct but interacting domains of Indian culture.','सूर्य प्रकाश, समय और जीवन के दृश्य स्रोत के रूप में पूजित हैं। अनुष्ठानिक श्रद्धा और खगोलीय अवलोकन भारतीय संस्कृति में अलग लेकिन परस्पर संपर्क रखने वाले क्षेत्र रहे हैं।'),
('chandra-calendar','Chandra and Indian time-reckoning','चंद्रमा और भारतीय कालगणना','Lunar phases are central to tithi and paksha calculations. This astronomical basis coexists with religious and festival meanings attached to lunar dates.','चंद्र कलाएँ तिथि और पक्ष की गणना का आधार हैं। यह खगोलीय आधार चंद्र तिथियों से जुड़े धार्मिक और पर्वीय अर्थों के साथ सह-अस्तित्व रखता है।'),
('rivers-as-mothers','Why are rivers honored as mothers?','नदियों को माता क्यों माना जाता है?','Rivers sustain settlement, agriculture, pilgrimage and ritual life. Calling a river mother expresses gratitude and sacred relationship as much as geography.','नदियाँ बसावट, कृषि, तीर्थ और अनुष्ठानिक जीवन को सहारा देती हैं। नदी को माता कहना भूगोल के साथ कृतज्ञता और पवित्र संबंध को भी व्यक्त करता है।'),
('panchamahabhuta','The five great elements','पंचमहाभूत','Earth, water, fire, air and space form a major conceptual vocabulary across several Hindu philosophical, medical and ritual traditions. Their meanings are traditional categories, not identical to the periodic table of modern chemistry.','पृथ्वी, जल, अग्नि, वायु और आकाश अनेक हिंदू दार्शनिक, चिकित्सीय और अनुष्ठानिक परंपराओं की प्रमुख अवधारणाएँ हैं। इनके अर्थ पारंपरिक श्रेणियाँ हैं, आधुनिक रसायन विज्ञान की आवर्त सारणी के समान नहीं।'),
('tree-reverence','Tree reverence and sacred ecology','वृक्ष-सम्मान और पवित्र पारिस्थितिकी','Peepal, banyan, tulsi and other plants carry ritual, medicinal, social and symbolic meanings. Respect for plants can be understood as part of a wider culture of gratitude toward life-supporting nature.','पीपल, वट, तुलसी और अन्य वनस्पतियों के अनुष्ठानिक, औषधीय, सामाजिक और प्रतीकात्मक अर्थ हैं। वनस्पतियों का सम्मान जीवनदायिनी प्रकृति के प्रति व्यापक कृतज्ञता का हिस्सा समझा जा सकता है।'),
('naga-reverence','Understanding Naga reverence','नाग-पूजा को समझें','Naga traditions combine sacred symbolism, regional mythology and reverence for powerful forms of life. They should not be reduced to a single literal explanation.','नाग परंपराएँ पवित्र प्रतीक, क्षेत्रीय कथाएँ और जीवन के शक्तिशाली रूपों के प्रति सम्मान को जोड़ती हैं। इन्हें किसी एक शाब्दिक व्याख्या तक सीमित नहीं करना चाहिए।'),
('gau-mata','Why is the cow called Gau Mata?','गौ माता क्यों कहा जाता है?','The cow became deeply associated with nourishment, agrarian life, dairy, dung as fuel and manure, generosity and ahimsa. Religious symbolism builds on this long civilizational relationship.','गाय पोषण, कृषि-जीवन, दुग्ध, ईंधन और खाद के रूप में गोबर, उदारता और अहिंसा से गहराई से जुड़ी रही है। धार्मिक प्रतीक इसी दीर्घ सभ्यतागत संबंध पर विकसित हुए।'),
('many-festival-stories','Why can one festival have many sacred stories?','एक पर्व की अनेक कथाएँ क्यों हो सकती हैं?','Hindu traditions developed across regions and communities over long periods. A festival can therefore preserve several theological memories without requiring one community to erase another.','हिंदू परंपराएँ लंबे समय में अनेक क्षेत्रों और समुदायों में विकसित हुईं। इसलिए एक पर्व कई धार्मिक स्मृतियों को साथ रख सकता है, बिना किसी एक परंपरा को मिटाए।'),
('many-hindu-calendars','Why are there several Hindu calendars?','अनेक हिंदू पंचांग क्यों हैं?','Regional calendars can differ in month reckoning, new-year conventions and calculation traditions while sharing common astronomical building blocks such as tithi and nakshatra.','क्षेत्रीय पंचांग मास-गणना, नववर्ष और गणना-पद्धति में भिन्न हो सकते हैं, जबकि तिथि और नक्षत्र जैसे सामान्य खगोलीय आधार साझा करते हैं।'),
('tithi-meaning','What is a Tithi?','तिथि क्या है?','A tithi is based on the angular separation of the Moon and Sun, divided into thirty parts across a synodic lunar month. Religious observance is then organized around these calculated lunar dates.','तिथि सूर्य और चंद्रमा के कोणीय अंतर पर आधारित है, जिसे एक चंद्र मास में तीस भागों में बाँटा जाता है। धार्मिक अनुष्ठान इन गणितीय चंद्र तिथियों के अनुसार व्यवस्थित होते हैं।'),
('nakshatra-meaning','What is a Nakshatra?','नक्षत्र क्या है?','The nakshatra system divides the ecliptic into a traditional sequence of lunar mansions used for calendrical and ritual reckoning.','नक्षत्र-पद्धति क्रांतिवृत्त को चंद्र-गति से जुड़ी पारंपरिक खगोलीय इकाइयों में बाँटती है, जिनका उपयोग पंचांग और अनुष्ठानिक कालगणना में होता है।'),
('rahu-ketu-nodes','Rahu and Ketu: sacred symbolism and lunar nodes','राहु और केतु: पवित्र प्रतीक और चंद्र-पथ के नोड','In astronomical calculation Rahu and Ketu correspond to the ascending and descending nodes of the Moon’s orbit. Mythic narratives give these eclipse points a sacred symbolic language.','खगोलीय गणना में राहु और केतु चंद्र-कक्षा के आरोही और अवरोही नोड से संबंधित हैं। पौराणिक कथाएँ इन ग्रहण-बिंदुओं को पवित्र प्रतीकात्मक भाषा देती हैं।'),
('eclipse-calculation','Indian traditions of eclipse calculation','भारतीय ग्रहण-गणना परंपरा','Indian mathematical astronomy developed numerical methods for predicting eclipses. Sacred stories and mathematical calculation operated as different kinds of explanation within the broader culture.','भारतीय गणितीय खगोलशास्त्र ने ग्रहणों की भविष्यवाणी के लिए संख्यात्मक विधियाँ विकसित कीं। पवित्र कथाएँ और गणितीय गणना व्यापक संस्कृति में अलग प्रकार की व्याख्याओं के रूप में साथ रही हैं।'),
('aryabhata-earth-rotation-understand','Aryabhata and Earth’s rotation','आर्यभट और पृथ्वी का घूर्णन','Aryabhata used Earth’s rotation to explain the apparent daily motion of the stars. This is a documented achievement of classical Indian mathematical astronomy.','आर्यभट ने तारों की प्रत्यक्ष दैनिक गति को समझाने में पृथ्वी के घूर्णन का उपयोग किया। यह शास्त्रीय भारतीय गणितीय खगोलशास्त्र की दस्तावेज़ित उपलब्धि है।'),
('zero-place-value-understand','Zero and the Indian place-value tradition','शून्य और भारतीय स्थान-मूल्य परंपरा','Indian mathematical traditions made foundational contributions to decimal place-value notation and arithmetic with zero. The history is strongest when described from manuscripts and mathematical texts rather than exaggerated slogans.','भारतीय गणितीय परंपराओं ने दशमलव स्थान-मूल्य पद्धति और शून्य के साथ अंकगणित में मूलभूत योगदान दिया। इस इतिहास को अतिशयोक्ति की बजाय पांडुलिपियों और गणितीय ग्रंथों के आधार पर समझना सबसे मजबूत है।'),
('sushruta-understand','Sushruta Samhita and surgery','सुश्रुत संहिता और शल्यचिकित्सा','The Sushruta Samhita preserves extensive discussions of surgical instruments, wounds, fractures, training and reconstructive procedures, making it a major source in the history of medicine.','सुश्रुत संहिता में शल्य-उपकरण, घाव, अस्थिभंग, प्रशिक्षण और पुनर्निर्माणात्मक प्रक्रियाओं का विस्तृत वर्णन है, इसलिए चिकित्सा-इतिहास में यह एक प्रमुख स्रोत है।'),
('panini-understand','Panini and the grammatical tradition','पाणिनि और व्याकरण परंपरा','The Ashtadhyayi presents an exceptionally compact rule system for Sanskrit grammar and became foundational for later grammatical scholarship in India.','अष्टाध्यायी संस्कृत व्याकरण के लिए अत्यंत संक्षिप्त नियम-पद्धति प्रस्तुत करती है और भारत की बाद की व्याकरण-परंपरा का मूल आधार बनी।'),
('gurukul-understand','What was the Gurukul ideal?','गुरुकुल का आदर्श क्या था?','The gurukul ideal emphasizes close teacher-student learning, discipline, memorization, reflection, conduct and subject-specific training. Historical institutions varied greatly by place and period.','गुरुकुल का आदर्श निकट गुरु-शिष्य संबंध, अनुशासन, स्मरण, मनन, आचरण और विषयानुसार प्रशिक्षण पर बल देता है। वास्तविक ऐतिहासिक संस्थाएँ स्थान और काल के अनुसार काफी भिन्न थीं।'),
('shastrartha-understand','Shastrartha: debate as a path of learning','शास्त्रार्थ: ज्ञान का तर्कपूर्ण संवाद','Indian intellectual traditions developed formal cultures of argument, commentary, objection and reply. Disagreement between schools was often treated as a way to sharpen understanding.','भारतीय बौद्धिक परंपराओं में तर्क, टीका, पूर्वपक्ष और उत्तर की विकसित संस्कृतियाँ थीं। विभिन्न मतों का असहमति-पूर्ण संवाद समझ को अधिक सूक्ष्म बनाने का माध्यम था।'),
('many-philosophies','Why does Hinduism contain many philosophies?','हिंदू धर्म में अनेक दर्शन क्यों हैं?','Hindu traditions preserve multiple philosophical systems because questions about reality, self, knowledge, devotion and liberation received more than one disciplined answer.','हिंदू परंपराओं में अनेक दर्शन इसलिए सुरक्षित हैं क्योंकि वास्तविकता, आत्मा, ज्ञान, भक्ति और मुक्ति के प्रश्नों के एक से अधिक अनुशासित उत्तर विकसित हुए।'),
('advaita-dvaita-vishishtadvaita','Advaita, Dvaita and Vishishtadvaita','अद्वैत, द्वैत और विशिष्टाद्वैत','These Vedanta schools share reverence for major scriptural sources while interpreting the relation between Brahman, individual selves and the world differently.','ये वेदांत परंपराएँ प्रमुख शास्त्रीय स्रोतों का सम्मान साझा करती हैं, पर ब्रह्मन्, जीव और जगत के संबंध को अलग-अलग ढंग से समझाती हैं।'),
('many-ramayanas','Why are there many Ramayana traditions?','रामायण की अनेक परंपराएँ क्यों हैं?','Valmiki Ramayana is foundational, yet poets and communities across India and Asia retold the sacred narrative in their own languages and devotional settings.','वाल्मीकि रामायण आधारभूत है, फिर भी भारत और एशिया के अनेक कवियों तथा समुदायों ने इस पवित्र कथा को अपनी भाषाओं और भक्तिपरंपराओं में पुनःकथित किया।'),
('mahabharata-beyond-war','Mahabharata is more than a war narrative','महाभारत केवल युद्ध-कथा नहीं है','The Mahabharata includes statecraft, ethics, pilgrimage, genealogy, philosophy, devotion and reflection on difficult duties in addition to the Kurukshetra war.','महाभारत में कुरुक्षेत्र युद्ध के साथ राज्यशास्त्र, नैतिकता, तीर्थ, वंशावली, दर्शन, भक्ति और कठिन कर्तव्यों पर गहरा चिंतन भी है।'),
('gita-part-mahabharata','Bhagavad Gita and the Mahabharata','भगवद्गीता और महाभारत','The Bhagavad Gita is embedded within the Bhishma Parva of the Mahabharata and presents the dialogue of Krishna and Arjuna before battle.','भगवद्गीता महाभारत के भीष्मपर्व में स्थित कृष्ण और अर्जुन के संवाद के रूप में प्रस्तुत होती है।'),
('shruti-smriti-itihasa-purana','Shruti, Smriti, Itihasa and Purana','श्रुति, स्मृति, इतिहास और पुराण','Hindu textual culture distinguishes several genres with different functions and histories. Treating every text as the same kind of authority obscures how the tradition actually works.','हिंदू ग्रंथ-परंपरा कई विधाओं को अलग पहचानती है, जिनके कार्य और इतिहास भिन्न हैं। सभी ग्रंथों को एक ही प्रकार की प्रामाणिकता मानना परंपरा की वास्तविक संरचना को अस्पष्ट कर देता है।'),
('manusmriti-not-single-bible','Hindu traditions do not have a single equivalent of one binding law-book','हिंदू परंपराओं में एक ही सर्वमान्य बाध्यकारी कानून-पुस्तक नहीं है','Dharmashastra is a large textual tradition with many works, commentaries and regional practices. Manusmriti is important historically, but it is not the sole text that defines Hindu belief and practice.','धर्मशास्त्र अनेक ग्रंथों, टीकाओं और क्षेत्रीय आचारों की विशाल परंपरा है। मनुस्मृति ऐतिहासिक रूप से महत्वपूर्ण है, पर वह हिंदू विश्वास और आचार को अकेले परिभाषित करने वाला एकमात्र ग्रंथ नहीं है।'),
('tantra-meaning','Tantra is broader than popular stereotypes','तंत्र लोकप्रिय धारणाओं से कहीं व्यापक है','Tantric traditions include mantra, deity worship, temple ritual, meditation, yoga, cosmology and philosophy. Reducing Tantra to a single sensational practice misrepresents its textual breadth.','तांत्रिक परंपराओं में मंत्र, देव-उपासना, मंदिर-अनुष्ठान, ध्यान, योग, ब्रह्मांड-विचार और दर्शन शामिल हैं। तंत्र को किसी एक सनसनीखेज अभ्यास तक सीमित करना उसकी ग्रंथीय व्यापकता को गलत दर्शाता है।'),
('temples-culture-centres','Temples as centres of worship, art and community','मंदिर: पूजा, कला और समुदाय के केंद्र','Across periods and regions, temples supported ritual life as well as architecture, sculpture, music, dance, patronage, festivals and local institutions.','अनेक कालों और क्षेत्रों में मंदिरों ने पूजा के साथ स्थापत्य, मूर्तिकला, संगीत, नृत्य, संरक्षण, उत्सव और स्थानीय संस्थाओं को भी सहारा दिया।'),
('ahimsa-compassion','Ahimsa, compassion and responsibility','अहिंसा, करुणा और जिम्मेदारी','Ahimsa became a major ethical ideal across Hindu, Jain and Buddhist traditions. Hindu texts also discuss difficult cases of duty, so the ideal is interpreted through context rather than a single simplistic rule.','अहिंसा हिंदू, जैन और बौद्ध परंपराओं में प्रमुख नैतिक आदर्श बनी। हिंदू ग्रंथ कठिन कर्तव्य-स्थितियों पर भी विचार करते हैं, इसलिए इस आदर्श को संदर्भ सहित समझा जाता है।'),
]

